    spec = importlib.util.spec_from_file_location("iv_base_resources", resource)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    rng = np.random.default_rng(7)
    Y, X, Z, beta, theta = module.generate_data(rng, n=50)
    assert Y.shape == (50,) and X.shape == (50, 5) and Z.shape == (50, 10)
    assert beta.shape == (5,) and theta.shape == (10, 5)
    assert np.isfinite(Y).all() and np.isfinite(X).all() and np.isfinite(Z).all()
    assert module.ols(Y, X).shape == (5,)
    assert module.two_sls(Y, X, Z).shape == (5,)
    # Confirm the controller-provided writable scratch location without writing
    # into the read-only package mount.
    with tempfile.TemporaryFile() as scratch:
        scratch.write(b"cpu-smoke")
    print("dependency imports and public synthetic starting resources: OK")


